#!/usr/bin/env bun

async function validateJson(): Promise<number> {
  try {
    const input = await Bun.stdin.text();

    if (input.trim() === '') {
      console.error('Error: Empty input provided');
      return 1;
    }

    JSON.parse(input);
    console.log('Valid JSON');
    return 0;
  } catch (error) {
    if (error instanceof SyntaxError) {
      console.error(`Invalid JSON: ${error.message}`);
    } else {
      console.error(`Error: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
    return 1;
  }
}

const exitCode = await validateJson();
process.exit(exitCode);

import { describe, test, expect } from 'bun:test';
import { $ } from 'bun';

describe('validate-json', () => {
  test('accepts valid JSON object', async () => {
    const result = await $`echo '{"name": "test", "value": 123}' | bun run src/validate-json.ts`.nothrow();
    expect(result.exitCode).toBe(0);
    expect(result.stdout.toString()).toContain('Valid JSON');
  });

  test('accepts valid JSON array', async () => {
    const result = await $`echo '[1, 2, 3, "test"]' | bun run src/validate-json.ts`.nothrow();
    expect(result.exitCode).toBe(0);
    expect(result.stdout.toString()).toContain('Valid JSON');
  });

  test('accepts valid JSON string', async () => {
    const result = await $`echo '"hello world"' | bun run src/validate-json.ts`.nothrow();
    expect(result.exitCode).toBe(0);
    expect(result.stdout.toString()).toContain('Valid JSON');
  });

  test('accepts valid JSON number', async () => {
    const result = await $`echo '42' | bun run src/validate-json.ts`.nothrow();
    expect(result.exitCode).toBe(0);
    expect(result.stdout.toString()).toContain('Valid JSON');
  });

  test('rejects invalid JSON with syntax error', async () => {
    const result = await $`echo '{invalid json}' | bun run src/validate-json.ts`.nothrow();
    expect(result.exitCode).toBe(1);
    expect(result.stderr.toString()).toContain('Invalid JSON');
  });

  test('rejects empty input', async () => {
    const result = await $`echo '' | bun run src/validate-json.ts`.nothrow();
    expect(result.exitCode).toBe(1);
    expect(result.stderr.toString()).toContain('Empty input');
  });

  test('rejects malformed JSON with missing quotes', async () => {
    const result = await $`echo '{name: test}' | bun run src/validate-json.ts`.nothrow();
    expect(result.exitCode).toBe(1);
    expect(result.stderr.toString()).toContain('Invalid JSON');
  });

  test('rejects incomplete JSON object', async () => {
    const result = await $`echo '{"incomplete":' | bun run src/validate-json.ts`.nothrow();
    expect(result.exitCode).toBe(1);
    expect(result.stderr.toString()).toContain('Invalid JSON');
  });
});

