import { describe, expect, test } from "bun:test";
import { greet, add, greetWithTime } from "./utils";

describe("utils", () => {
  test("greet returns greeting message", () => {
    expect(greet("Alice")).toBe("Hello, Alice!");
  });

  test("add returns sum of two numbers", () => {
    expect(add(2, 3)).toBe(5);
  });

  test("greetWithTime returns morning greeting", () => {
    expect(greetWithTime("Alice", 8)).toBe("Good morning, Alice!");
  });

  test("greetWithTime returns afternoon greeting", () => {
    expect(greetWithTime("Bob", 14)).toBe("Good afternoon, Bob!");
  });

  test("greetWithTime returns evening greeting", () => {
    expect(greetWithTime("Charlie", 20)).toBe("Good evening, Charlie!");
  });
});

