/**
 * High-performance JSON validation utility.
 */

export interface ValidationResult {
  valid: boolean;
  error?: string;
  position?: number;
}

/**
 * Validates JSON string content for syntactic correctness.
 * Uses Bun's native JSON parser for optimal performance.
 */
export function validateJson(content: string): ValidationResult {
  if (content.length === 0) {
    return {
      valid: false,
      error: "Empty input",
      position: 0,
    };
  }

  try {
    JSON.parse(content);
    return { valid: true };
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    const positionMatch = message.match(/position (\d+)/);
    const position = positionMatch ? parseInt(positionMatch[1], 10) : undefined;

    return {
      valid: false,
      error: message,
      position,
    };
  }
}

/**
 * Validates JSON content from a file with streaming support for large files.
 * For optimal performance, reads entire file and validates.
 */
export async function validateJsonFile(filePath: string): Promise<ValidationResult> {
  try {
    const file = Bun.file(filePath);
    const exists = await file.exists();

    if (!exists) {
      return {
        valid: false,
        error: `File not found: ${filePath}`,
      };
    }

    const content = await file.text();
    return validateJson(content);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return {
      valid: false,
      error: `Failed to read file: ${message}`,
    };
  }
}

/**
 * CLI entry point for JSON validation.
 * Supports file paths as arguments or stdin input.
 */
export async function main(args: string[]): Promise<number> {
  if (args.length === 0) {
    const stdinContent = await readStdin();
    const result = validateJson(stdinContent);
    printResult(result, "<stdin>");
    return result.valid ? 0 : 1;
  }

  let hasErrors = false;

  for (const filePath of args) {
    const result = await validateJsonFile(filePath);
    printResult(result, filePath);
    if (!result.valid) {
      hasErrors = true;
    }
  }

  return hasErrors ? 1 : 0;
}

/**
 * Reads all content from stdin.
 */
async function readStdin(): Promise<string> {
  const chunks: Uint8Array[] = [];
  const reader = Bun.stdin.stream().getReader();

  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      chunks.push(value);
    }
  } finally {
    reader.releaseLock();
  }

  const totalLength = chunks.reduce((sum, chunk) => sum + chunk.length, 0);
  const combined = new Uint8Array(totalLength);
  let offset = 0;
  for (const chunk of chunks) {
    combined.set(chunk, offset);
    offset += chunk.length;
  }

  return new TextDecoder().decode(combined);
}

/**
 * Prints validation result to console.
 */
function printResult(result: ValidationResult, source: string): void {
  if (result.valid) {
    console.log(`✓ ${source}: Valid JSON`);
  } else {
    console.error(`✗ ${source}: Invalid JSON`);
    if (result.error) {
      console.error(`  Error: ${result.error}`);
    }
  }
}

if (import.meta.main) {
  const exitCode = await main(process.argv.slice(2));
  process.exit(exitCode);
}

import { describe, expect, test, beforeEach, afterEach } from "bun:test";
import { validateJson, validateJsonFile, main } from "./validate-json";
import { writeFileSync, unlinkSync, mkdirSync, rmSync } from "fs";
import { join } from "path";

describe("validateJson", () => {
  test("returns valid for correct JSON object", () => {
    const result = validateJson('{"name": "Alice", "age": 30}');
    expect(result.valid).toBe(true);
    expect(result.error).toBeUndefined();
  });

  test("returns valid for correct JSON array", () => {
    const result = validateJson('[1, 2, 3, "test"]');
    expect(result.valid).toBe(true);
  });

  test("returns valid for nested JSON", () => {
    const result = validateJson('{"user": {"name": "Bob", "scores": [90, 85, 95]}}');
    expect(result.valid).toBe(true);
  });

  test("returns valid for JSON primitives", () => {
    expect(validateJson('"string"').valid).toBe(true);
    expect(validateJson("123").valid).toBe(true);
    expect(validateJson("true").valid).toBe(true);
    expect(validateJson("null").valid).toBe(true);
  });

  test("returns invalid for malformed JSON with missing brace", () => {
    const result = validateJson('{"name": "Alice"');
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });

  test("returns invalid for trailing comma", () => {
    const result = validateJson('{"name": "Alice",}');
    expect(result.valid).toBe(false);
  });

  test("returns invalid for unquoted keys", () => {
    const result = validateJson('{name: "Alice"}');
    expect(result.valid).toBe(false);
  });

  test("returns invalid for single quotes", () => {
    const result = validateJson("{'name': 'Alice'}");
    expect(result.valid).toBe(false);
  });

  test("returns invalid for empty input", () => {
    const result = validateJson("");
    expect(result.valid).toBe(false);
    expect(result.error).toBe("Empty input");
    expect(result.position).toBe(0);
  });

  test("returns invalid for whitespace only", () => {
    const result = validateJson("   ");
    expect(result.valid).toBe(false);
  });

  test("returns invalid for undefined value", () => {
    const result = validateJson("undefined");
    expect(result.valid).toBe(false);
  });
});

describe("validateJsonFile", () => {
  const testDir = join(process.cwd(), "test-tmp");

  beforeEach(() => {
    mkdirSync(testDir, { recursive: true });
  });

  afterEach(() => {
    rmSync(testDir, { recursive: true, force: true });
  });

  test("validates valid JSON file", async () => {
    const filePath = join(testDir, "valid.json");
    writeFileSync(filePath, '{"status": "ok"}');

    const result = await validateJsonFile(filePath);
    expect(result.valid).toBe(true);
  });

  test("detects invalid JSON in file", async () => {
    const filePath = join(testDir, "invalid.json");
    writeFileSync(filePath, '{"status": "ok"');

    const result = await validateJsonFile(filePath);
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });

  test("handles non-existent file", async () => {
    const result = await validateJsonFile(join(testDir, "missing.json"));
    expect(result.valid).toBe(false);
    expect(result.error).toContain("File not found");
  });

  test("handles large valid JSON file", async () => {
    const filePath = join(testDir, "large.json");
    const largeArray = Array.from({ length: 10000 }, (_, i) => ({
      id: i,
      name: `Item ${i}`,
      value: Math.random(),
    }));
    writeFileSync(filePath, JSON.stringify(largeArray));

    const result = await validateJsonFile(filePath);
    expect(result.valid).toBe(true);
  });

